'use strict';
let sequenceView='steps',rollZoomed=false,rollPage=0,rollFollow=true,rollSelected=null,rollDrag=null,rollTouch=null,resampling=false;
const rollRow=28,rollHighest=24,rollLowest=-24;let rollCell=32;
function currentPattern(){return state.patterns[state.pattern]}
function noteName(pitch){return pitch===0?'Base':(pitch>0?'+':'')+pitch}
function editGrid(){return +$('#rollGrid').value||1/24}
function ensureNoteSelection(){if(rollSelected&&(!currentPattern().notes.includes(rollSelected)||rollSelected.pad!==state.selected))rollSelected=null}
function renderNoteInspector(){ensureNoteSelection();const n=rollSelected;$('#noteSummary').textContent=n?noteName(n.pitch)+' · temps '+(n.step+1).toFixed(2)+' · '+Math.round(n.velocity*100)+' %':'Touche la grille pour ajouter une note.';for(const id of ['noteDuration','noteVelocity','noteCopy','noteDelete'])$('#'+id).disabled=!n;if(n){const select=$('#noteDuration');select.querySelector('[data-custom]')?.remove();if(![.5,1,2,4,8,16].includes(n.duration)){const o=document.createElement('option');o.dataset.custom='1';o.value=n.duration;o.textContent=n.duration.toFixed(2)+' pas';select.append(o)}select.value=n.duration;$('#noteVelocity').value=n.velocity*100}}
function renderRoll(center=false){if(sequenceView!=='notes')return;ensureNoteSelection();const host=$('#rollScroll'),world=$('#rollWorld'),p=currentPattern(),width=Math.max(220,host.clientWidth-40);rollCell=rollZoomed?40:width/16;world.style.width=(40+16*rollCell)+'px';world.style.height=((rollHighest-rollLowest+1)*rollRow+22)+'px';world.style.setProperty('--cell',rollCell+'px');$('#rollRuler')?.remove();const ruler=document.createElement('div');ruler.id='rollRuler';for(let beat=0;beat<4;beat++){const tick=document.createElement('span');tick.textContent=String(beat+1);tick.style.left=(40+beat*4*rollCell)+'px';ruler.append(tick)}world.append(ruler);$('#rollKeys').replaceChildren();for(let pitch=rollHighest;pitch>=rollLowest;pitch--){const key=document.createElement('button');key.className='roll-key'+([1,3,6,8,10].includes((pitch%12+12)%12)?' black':'');key.style.top=(22+(rollHighest-pitch)*rollRow)+'px';key.textContent=noteName(pitch);key.setAttribute('aria-label','Écouter le son '+noteName(pitch));key.onpointerdown=e=>{e.preventDefault();key.setPointerCapture(e.pointerId);hit(state.selected,'rollkey:'+e.pointerId,pitch,{ignoreTool:true,gate:true})};const off=e=>release('rollkey:'+e.pointerId);key.onpointerup=off;key.onpointercancel=off;key.onlostpointercapture=off;$('#rollKeys').append(key)}$('#rollNotes').replaceChildren();for(const n of p.notes)if(n.pad===state.selected&&n.step<rollPage*16+16&&n.step+n.duration>rollPage*16&&n.pitch<=rollHighest&&n.pitch>=rollLowest){const b=document.createElement('button');b.className='roll-note'+(n===rollSelected?' selected':'');b.style.left=(40+Math.max(0,n.step-rollPage*16)*rollCell)+'px';b.style.top=(23+(rollHighest-n.pitch)*rollRow)+'px';b.style.width=Math.max(9,StudioNotes.visible(n,rollPage)*rollCell-2)+'px';b.style.opacity=.4+n.velocity*.6;b.textContent=noteName(n.pitch);b.setAttribute('aria-label',noteName(n.pitch)+', temps '+(n.step+1).toFixed(2)+', durée '+n.duration.toFixed(2)+' pas');const handle=document.createElement('i');handle.className='note-end';handle.setAttribute('aria-hidden','true');b.append(handle);b.onpointerdown=e=>{e.preventDefault();e.stopPropagation();rollSelected=n;remember();rollDrag={id:e.pointerId,n,owner:state,pattern:p,original:{...n},x:e.clientX,y:e.clientY,resize:e.target===handle};b.setPointerCapture(e.pointerId);renderNoteInspector();$$('.roll-note').forEach(el=>el.classList.toggle('selected',el===b))};b.onpointermove=e=>moveRollNote(e,b);const finish=e=>finishRollDrag(e);b.onpointerup=finish;b.onpointercancel=e=>finishRollDrag(e,true);b.onlostpointercapture=finish;b.onclick=e=>{if(e.detail===0){rollSelected=n;renderRoll()}};b.onkeydown=e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Delete','Backspace'].includes(e.key)){e.preventDefault();rollSelected=n;if(e.key==='Delete'||e.key==='Backspace')$('#noteDelete').onclick();else mutateNote(n=>{if(e.key==='ArrowUp')n.pitch++;if(e.key==='ArrowDown')n.pitch--;if(e.key==='ArrowLeft')n.step-=editGrid();if(e.key==='ArrowRight')n.step+=editGrid()})}};$('#rollNotes').append(b)}renderNoteInspector();if(center){const pitches=p.notes.filter(n=>n.pad===state.selected&&Math.floor(n.step/16)===rollPage).map(n=>n.pitch),top=pitches.length?Math.min(rollHighest,Math.max(...pitches)+1):3;host.scrollTop=Math.max(0,(rollHighest-top)*rollRow)}updateRollPlayhead(-1)}
function moveRollNote(e,b){const d=rollDrag;if(!d||d.id!==e.pointerId||d.owner!==state)return;const grid=editGrid(),dx=(e.clientX-d.x)/rollCell,dy=Math.round((e.clientY-d.y)/rollRow),n=d.n;if(d.resize)n.duration=d.original.duration+Math.round(dx/grid)*grid;else{n.step=d.original.step+Math.round(dx/grid)*grid;n.pitch=d.original.pitch-dy}Object.assign(n,StudioNotes.normalize(n,currentPattern().bars*16,grid));b.style.left=(40+Math.max(0,n.step-rollPage*16)*rollCell)+'px';b.style.top=(23+(rollHighest-n.pitch)*rollRow)+'px';b.style.width=Math.max(9,StudioNotes.visible(n,rollPage)*rollCell-2)+'px';renderNoteInspector()}
function finishRollDrag(e,cancel=false){const d=rollDrag;if(!d||e.pointerId!==d.id)return;rollDrag=null;if(d.owner!==state||!state.patterns.includes(d.pattern))return;if(cancel)Object.assign(d.n,d.original);else{changed();renderPatterns()}renderRoll()}
$('#rollWorld').onpointerdown=e=>{if(e.target.closest('button'))return;rollTouch={id:e.pointerId,x:e.clientX,y:e.clientY}};
$('#rollWorld').onpointerup=e=>{const touch=rollTouch;rollTouch=null;if(!touch||touch.id!==e.pointerId||Math.hypot(e.clientX-touch.x,e.clientY-touch.y)>8||e.target.closest('button'))return;const r=$('#rollWorld').getBoundingClientRect(),x=e.clientX-r.left-40,y=e.clientY-r.top-22;if(x<0||y<0)return;if(state.pads[state.selected].data.length<2){message('Ajoute un son à ce pad avant d’écrire ses notes.');return}const step=rollPage*16+Math.floor(x/rollCell/editGrid())*editGrid(),pitch=rollHighest-Math.floor(y/rollRow);if(step>=(rollPage+1)*16||pitch<rollLowest)return;const p=currentPattern(),existing=p.notes.find(n=>n.pad===state.selected&&Math.abs(n.step-step)<1/48&&n.pitch===pitch);if(existing){rollSelected=existing;renderRoll();return}try{const n=StudioNotes.normalize({pad:state.selected,step,pitch,duration:Math.max(editGrid(),1),velocity:.85,gated:true},p.bars*16,editGrid());remember();M.put(p,n);rollSelected=p.notes.find(n=>n.pad===state.selected&&n.step===step&&n.pitch===pitch);changed();renderPatterns();renderRoll();hit(state.selected,null,pitch,{ignoreTool:true,gate:true})}catch(err){message(err.message)}};
$('#rollWorld').onpointercancel=()=>rollTouch=null;
function mutateNote(fn){ensureNoteSelection();if(!rollSelected)return;remember();fn(rollSelected);Object.assign(rollSelected,StudioNotes.normalize(rollSelected,currentPattern().bars*16,1/24));changed();renderPatterns();renderRoll()}
$('#noteDuration').onchange=()=>mutateNote(n=>n.duration=+$('#noteDuration').value);$('#noteVelocity').onpointerdown=remember;$('#noteVelocity').oninput=()=>{if(!rollSelected)return;rollSelected.velocity=+$('#noteVelocity').value/100;changed();renderNoteInspector()};$('#noteVelocity').onchange=()=>renderRoll();$('#noteDelete').onclick=()=>{if(!rollSelected)return;remember();currentPattern().notes=currentPattern().notes.filter(n=>n!==rollSelected);rollSelected=null;changed();renderPatterns();renderRoll()};$('#noteCopy').onclick=()=>{if(!rollSelected)return;const p=currentPattern(),n={...rollSelected,step:rollSelected.step+rollSelected.duration};if(n.step>=p.bars*16){message('Pas assez de place après cette note.');return}if(p.notes.some(x=>x.pad===n.pad&&x.pitch===n.pitch&&Math.abs(x.step-n.step)<1/48)){message('Une note existe déjà à cet endroit.');return}remember();M.put(p,n);rollSelected=p.notes[p.notes.length-1];rollPage=Math.floor(n.step/16);page=rollPage;changed();renderPatterns();renderSteps()};
function setSequenceView(view){sequenceView=view;$('#screen-compose').classList.toggle('notes-mode',view==='notes');$('#steps').hidden=view==='notes';$('#noteRoll').hidden=view!=='notes';$('#loopSelect').hidden=view!=='notes';$('#stepView').classList.toggle('active',view==='steps');$('#noteView').classList.toggle('active',view==='notes');rollPage=page;if(view==='notes')requestAnimationFrame(()=>renderRoll(true))}
$('#stepView').onclick=()=>setSequenceView('steps');$('#noteView').onclick=()=>setSequenceView('notes');$('#rollZoom').onclick=()=>{rollZoomed=!rollZoomed;$('#rollZoom').textContent=rollZoomed?'Zoom −':'Zoom +';renderRoll()};$('#rollFollow').onclick=()=>{rollFollow=!rollFollow;$('#rollFollow').setAttribute('aria-pressed',rollFollow);$('#rollFollow').classList.toggle('active',rollFollow)};
function updateRollPlayhead(current){const line=$('#rollPlayhead');line.hidden=current<0||!playing||page!==rollPage;if(!line.hidden)line.style.left=(40+current*rollCell)+'px'}
const stepsCore=renderSteps;renderSteps=(current=-1)=>{stepsCore(current);if(sequenceView==='notes'&&screen==='compose'){if(current<0){rollPage=page;renderRoll()}else{if(rollFollow&&rollPage!==page&&!rollDrag){rollPage=page;renderRoll()}updateRollPlayhead(current)}}};const patternsCore=renderPatterns;renderPatterns=()=>{patternsCore();const select=$('#loopSelect');select.replaceChildren();for(let i=0;i<8;i++){const o=document.createElement('option');o.value=i;o.textContent=state.patterns[i].name;select.append(o)}select.value=state.pattern};$('#loopSelect').onchange=()=>{$$('#patterns .pattern')[+$('#loopSelect').value].click()};
$('#loopToolsOpen').onclick=()=>open('loopTools');$('#patternCopy').addEventListener('click',()=>$('#loopTools').close());
function changeLoop(fn){try{const index=state.pattern,p=fn(currentPattern());remember();stop();state.pattern=index;state.patterns[index]=p;page=0;rollSelected=null;changed();render();$('#loopTools').close()}catch(e){message(e.message)}}
$('#doubleLoop').onclick=()=>changeLoop(StudioNotes.doubled);$('#halfLoop').onclick=()=>changeLoop(StudioNotes.halved);$('#reverseNotes').onclick=()=>{remember();const p=currentPattern();p.notes=p.notes.map(n=>n.pad===state.selected?StudioNotes.reverse([n],p.bars*16)[0]:n);rollSelected=null;changed();render();$('#loopTools').close()};
$('#noteQuantizeOpen').onclick=()=>{$('#recordGrid').value=state.recordGrid??1;open('quantizeSheet')};$('#recordGrid').onchange=()=>{remember();state.recordGrid=+$('#recordGrid').value;changed()};$('#quantizeStrength').oninput=()=>$('#quantizeValue').textContent=$('#quantizeStrength').value+' %';$('#applyQuantize').onclick=()=>{remember();const p=currentPattern();p.notes=p.notes.map(n=>n.pad===state.selected?StudioNotes.quantize([n],p.bars*16,+$('#quantizeGrid').value,+$('#quantizeStrength').value/100)[0]:n);rollSelected=null;changed();render();$('#quantizeSheet').close()};
async function resampleCurrentLoop(){if(resampling)return;const target=state.pads.findIndex(p=>p.data.length<2);if(target<0){message('Libère un pad pour y placer la boucle.');return}const owner=state,revisionAtStart=revision,patternAtStart=state.pattern,bpmAtStart=state.bpm;resampling=true;$('#resampleLoop').disabled=true;$('#resampleStatus').textContent='Rendu de la boucle avec ses effets…';try{const result=await renderLoop();if(owner!==state||revision!==revisionAtStart||state.pattern!==patternAtStart||state.bpm!==bpmAtStart||state.pads[target].data.length>1)throw Error('Le projet a changé pendant le rendu. Relance le rééchantillonnage.');const data=result.getChannelData(0).slice(),right=result.getChannelData(1).slice();audioMemory(target,data,right);remember();state.pads[target]={...M.blank(),name:currentPattern().name+' mix',data,right};state.selected=target;state.bank=Math.floor(target/16);changed();render();$('#loopTools').close();showEditor();message('Boucle et fins d’effets placées sur '+label(target)+'. Les pistes restent disponibles.')}catch(e){$('#resampleStatus').textContent=e.message;message(e.message)}finally{resampling=false;$('#resampleLoop').disabled=false}}
$('#resampleLoop').onclick=resampleCurrentLoop;
$('#cropSample').onclick=()=>{const p=state.pads[state.selected],a=Math.floor(p.start*p.data.length),b=Math.floor(p.end*p.data.length);if(a===0&&b===p.data.length)return;remember();audio.stop(state.selected);p.data=p.data.slice(a,b);p.right=p.right?p.right.slice(a,b):null;p.start=0;p.end=1;changed();render();message('Seule la sélection est conservée. Annuler récupère l’original.')};
$('#exportSample').onclick=async()=>{try{await unlock();const p=state.pads[state.selected],a=Math.floor(p.start*p.data.length),b=Math.floor(p.end*p.data.length),buffer=audio.ctx.createBuffer(p.right?2:1,Math.max(1,b-a),RATE);buffer.copyToChannel(p.data.subarray(a,b),0);if(p.right)buffer.copyToChannel(p.right.subarray(a,b),1);download(wav(buffer),safeName(p.name)+'.wav');message('Sélection exportée en WAV, sans effets ni changement de hauteur.')}catch(e){message(e.message)}};
window.addEventListener('resize',()=>{if(screen==='compose'&&sequenceView==='notes')renderRoll()});renderPatterns();

function renderKeyboardTransport(){$('#keyRecord').setAttribute('aria-pressed',armed);$('#keyRecord').classList.toggle('armed',armed);$('#keyRecord').textContent=armed?'● Rec armé':'Rec notes';$('#keyPlay').textContent=playing?'■ Arrêter la boucle':'▶ Jouer la boucle'}
$('#keyboardOpen').addEventListener('click',renderKeyboardTransport);$('#keyPlay').onclick=async()=>{await start();renderKeyboardTransport()};$('#keyRecord').onclick=()=>{$('#record').onclick();renderKeyboardTransport()};const stopCompositionCore=stop;stop=()=>{stopCompositionCore();renderKeyboardTransport();updateRollPlayhead(-1)};
